 const $=s=>document.querySelector(s),panel=$('#panel-solar');let settings=solarSettings(getState().solar),contextRoot=new THREE.Group(),pathRoot=new THREE.Group(),map=null,worker=null,result=null,scaleMode='results';const display={show:true,opacity:1,neutral:true},originalMaterials=new WeakMap(),originalBackground=scene.background.clone();let selected=null,pointerStart=null,request=null,runId=0;
 scene.add(contextRoot,pathRoot);const sun=new THREE.DirectionalLight(0xfff0c4,3.3);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.bias=-.00015;sun.shadow.normalBias=.08;scene.add(sun,sun.target);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
 panel.innerHTML=`<p class="panel-intro">Sunlight, irradiation, daylight potential and sky exposure.</p><label class="solar-switch"><input id="solar-enabled" type="checkbox"> Show sun path and shadows</label><div class="solar-fields"><label>Latitude (°)<input data-solar="lat" type="number" min="-89" max="89" step=".0001"></label><label>Longitude (° east)<input data-solar="lon" type="number" min="-180" max="180" step=".0001"></label><label>UTC offset (hours)<input data-solar="utc" type="number" min="-12" max="14" step=".25"></label><label>North rotation (°)<input data-solar="north" type="number" min="-180" max="180" step="1"></label></div><p class="note">Default: Cairo, UTC+2. Set the actual UTC offset for your chosen date, including daylight saving. North 0° = plan +Y; positive rotates north toward +X.</p><label class="solar-field">Date<input data-solar="date" type="date"></label><label class="solar-field">Local clock time <output id="solar-clock"></output><input data-solar="hour" type="range" min="0" max="23.75" step=".25"></label><p id="solar-position" class="note"></p><details><summary>Neighbouring buildings</summary><p class="note">Opaque axis-aligned blocks, in plan metres. Comparison designs are excluded.</p><div id="solar-context"></div><button id="solar-add-context" class="button add">＋ Add context block</button></details><div class="section-label spaced">Environmental study</div><label class="solar-field">Analysis<select data-solar="analysis"><option value="sunlight">Sunlight hours — geometry only</option><option value="radiation">Solar irradiation — weather-based estimate</option><option value="daylight">Daylight potential — façade VSC</option><option value="sky">Sky exposure — horizontal sky-view factor</option></select></label><p id="radiation-note" class="note" hidden>Open-Meteo free service for personal / academic non-commercial use. Location and date are sent to Open-Meteo. Hourly modelled weather; not on-site measurements. Dates older than five days use ERA5 reanalysis; recent dates use forecast data. A fixed UTC offset defines the 24-hour day. Radiation uses a maximum 5-minute geometric step with hourly weather held constant.</p><div id="daylight-controls" hidden><p class="note">Geometry-only screening; no weather request. VSC uses a virtual vertical plane facing outward at each façade sample under a CIE standard overcast sky. Sky-view factor uses a horizontal receiving plane, even at façade points. Date, location and sun settings do not affect these results. No glazing, interiors, reflected light or compliance assessment.</p><label class="solar-field">Sky sampling<select data-solar="skyResolution"><option value="16">512 rays — quick</option><option value="32">2,048 rays — standard</option><option value="64">8,192 rays — finer</option></select></label><p class="note">Compare standard and finer sampling around small openings or overhangs. VSC and sky-view factor are different metrics; their percentages are not interchangeable.</p></div><label class="solar-field">Sample surfaces<select data-solar="target"><option value="ground">Ground around building</option><option value="roof">Upward surfaces / roofs</option><option value="facade">Façades / vertical surfaces</option></select></label><label class="solar-field">Ground half-width (m)<input data-solar="extent" type="number" min="50" max="500" step="10"></label><label class="solar-field">Time step<select data-solar="step"><option value="15">15 minutes — finer</option><option value="30">30 minutes</option><option value="60">60 minutes — faster</option></select></label><button id="solar-run" class="button dark">Calculate sunlight hours</button><button id="solar-cancel" class="button" hidden>Cancel</button><p id="solar-status" role="status" aria-live="polite" class="note">One selected day; 500 surface samples or a 25 × 25 ground grid.</p><div class="solar-results-tools"><label class="solar-field">Colour scale<select id="solar-scale"><option value="results">Actual result range — reveal differences</option><option value="daylight">0 to daylight hours — compare runs</option></select></label><label class="solar-switch"><input id="solar-show-model" type="checkbox" checked> Show building</label><label class="solar-switch"><input id="solar-neutral" type="checkbox" checked> Neutral grey analysis view</label><label class="solar-field">Building opacity<input id="solar-opacity" type="range" min="0.1" max="1" step="0.1" value="1"></label><label id="radiation-scale-field" class="solar-field" hidden>Fixed scale maximum (kWh/m²)<input id="radiation-scale-max" type="number" min="0.1" max="100" step="0.5" value="10"></label><p id="solar-weather" class="note"></p><p id="solar-statistics" class="note"></p><p id="solar-selected" role="status" aria-live="polite" class="sample-readout">Run an analysis, then click or tap a coloured point.</p></div><button id="solar-csv" class="button add" disabled>Export analysis CSV</button><p class="note">Sunlight hours use geometry only. Irradiation = direct + isotropic sky diffuse with 512 sky directions for obstruction. No ground reflections, interreflections, glazing transmission or PV output. Opaque geometry and approximate sun positions; an early-design estimate, not a validated research engine. <a href="./validation.html" target="_blank" rel="noopener">View numerical checks and limits</a>. <a href="https://open-meteo.com/" target="_blank" rel="noopener">Weather: Open-Meteo (CC BY 4.0)</a>. <a href="https://pvlib-python.readthedocs.io/en/stable/reference/generated/pvlib.irradiance.isotropic.html" target="_blank" rel="noopener">Isotropic sky reference</a>. <a href="https://gml.noaa.gov/grad/solcalc/solareqns.PDF" target="_blank" rel="noopener">Solar method: NOAA</a>.</p>`;
 const clearRoot=root=>{for(const o of [...root.children]){o.traverse(n=>{n.geometry?.dispose();n.material?.dispose();});root.remove(o);}};
