   model=getModel();const own=triangles(model),all=new Float64Array([...own,...triangles(contextRoot)]);model.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});model=null;
   if(snapshot.analysis==='daylight'&&snapshot.target!=='facade')throw Error('Select façades for VSC.');let samples;if(snapshot.target==='ground'){samples=[];for(let x=0;x<25;x++)for(let z=0;z<25;z++)samples.push({position:[-snapshot.extent+(x+.5)*snapshot.extent*2/25,.04,-snapshot.extent+(z+.5)*snapshot.extent*2/25],normal:[0,1,0]});}else samples=sampleSurfaces(own,snapshot.target);
